INSERT INTO public.bpei_assessment_questions(level,ordinal,domain,question,evaluator_answer) VALUES
(3,1,'Identités','Quelle différence entre compte local et domaine Active Directory ?','Le compte de domaine est centralisé et soumis aux politiques du domaine.'),
(3,2,'Identités','À quoi sert une GPO en environnement Windows ?','Distribuer des règles de sécurité et de configuration à des objets ciblés.'),
(3,3,'DNS','Que provoque un enregistrement A incorrect ?','Une résolution vers une mauvaise adresse IPv4 et une indisponibilité possible.'),
(3,4,'DNS','Quelle différence entre CNAME et enregistrement A ?','CNAME renvoie à un autre nom ; A contient directement une IPv4.'),
(3,5,'Réseau','Pourquoi segmenter le réseau en VLAN ?','Séparer logiquement des flux et appliquer des règles adaptées.'),
(3,6,'Réseau','Quelles limites d''un traceroute pour diagnostiquer une coupure ?','ICMP peut être filtré et les routes asymétriques rendent des sauts trompeurs.'),
(3,7,'Réseau','Que se passe-t-il avec deux DHCP concurrents ?','Des paramètres IP incohérents et des pannes intermittentes peuvent apparaître.'),
(3,8,'Réseau','Comment analyser une boucle Ethernet en réseau commuté ?','Examiner tempêtes de broadcast, topologie et état du protocole STP.'),
(3,9,'Wi-Fi','Quels critères pour installer plusieurs bornes professionnelles ?','Couverture radio, canaux, capacité, alimentation, sécurité et roaming.'),
(3,10,'VPN','Un VPN suffit-il à sécuriser un ordinateur infecté ?','Non, il chiffre un transport et n''assainit pas le terminal compromis.'),
(3,11,'Pare-feu','Comment documenter une règle de pare-feu correctement ?','Source, destination, protocole, justification, responsable et durée.'),
(3,12,'Sauvegarde','Que signifient RPO et RTO ?','RPO est la perte de données admissible ; RTO le délai de reprise.'),
(3,13,'Sauvegarde','Pourquoi simuler une restauration complète de serveur ?','Pour vérifier intégrité, dépendances, délais réels et procédures de reprise.'),
(3,14,'Virtualisation','Pourquoi un snapshot ne remplace pas une sauvegarde ?','Il dépend souvent du stockage initial et ne garantit pas de récupération hors sinistre.'),
(3,15,'Serveurs','Comment préparer une mise à jour d''un serveur critique ?','Évaluer risques, sauvegarder, prévoir rollback et vérifier après maintenance.'),
(3,16,'Linux','Qu''indique la permission Linux 640 sur un fichier ?','Lecture/écriture propriétaire, lecture groupe et aucun accès aux autres.'),
(3,17,'Linux','Comment diagnostiquer un service systemd en échec ?','Lire systemctl status, journalctl, dépendances et droits du service.'),
(3,18,'Sécurité','Pourquoi prioriser les correctifs selon le risque ?','L''exposition, l''exploitabilité et l''impact métier varient entre vulnérabilités.'),
(3,19,'Sécurité','À quoi sert un collecteur centralisé de journaux ?','Corréler événements, détecter anomalies et préserver la chronologie.'),
(3,20,'E-mail','Quels rôles de SPF, DKIM et DMARC ?','SPF autorise des sources, DKIM signe, DMARC gère alignement et politique.'),
(3,21,'Cloud','Quels points vérifier avant de migrer les fichiers d''une PME ?','Droits, localisation, sauvegardes, confidentialité, contrats et réversibilité.'),
(3,22,'Données','À quoi correspond l''acronyme ACID en base de données ?','Atomicité, cohérence, isolation et durabilité des transactions.'),
(3,23,'Application','Quelle distinction entre réponses HTTP 401 et 403 ?','401 demande authentification ; 403 interdit l''accès dans le contexte.'),
(3,24,'Incident','Comment piloter une panne touchant plusieurs utilisateurs ?','Évaluer l''impact, communiquer, contenir, restaurer puis analyser les causes.'),
(3,25,'RGPD','Différence entre anonymisation et pseudonymisation ?','Une pseudonymisation conserve la possibilité de réidentifier sous conditions.');